import{_ as e,o as d,c as a,a2 as r}from"./chunks/framework.Cu3jFwFD.js";const m=JSON.parse('{"title":"Audio","description":"","frontmatter":{},"headers":[],"relativePath":"features/audio/design.md","filePath":"features/audio/design.md","lastUpdated":1795074279000}'),o={name:"features/audio/design.md"};function s(i,t,c,n,h,l){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="audio" tabindex="-1">Audio <a class="header-anchor" href="#audio" aria-label="Permalink to &quot;Audio&quot;">​</a></h1><p><strong>Status:</strong> <span class="status-badge status-idea">IDEA</span> · <strong>Updated:</strong> 2026-11-19 · <a href="./../../GDD">GDD</a></p><p>The full list of sounds and music the MVP needs, grouped by where they play. Each row names the moment that triggers it, so audio can be built and checked against the other specs. Serves <strong>Whimsical and comedic</strong> (voice blips, cartoon hits) and <strong>Push your luck</strong> (the storm and overtime are heard before they are seen) (<a class="decision-ref" href="/hex-gdd/GDD#d-081">D‑081</a>).</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ol><li><strong>Mix buses:</strong> Master → Music, Effects (SFX + ambience), Voice. The three volume sliders in Settings (<a class="decision-ref" href="/hex-gdd/GDD#d-073">D‑073</a>) drive Master, Music and Effects; Voice follows Effects.</li><li><strong>Priority when busy:</strong> hazard warnings and damage are never cut; ambience and engine duck first. Music ducks under the scam reveal and the wreck.</li><li><strong>3D or 2D:</strong> world sounds (strikes, other cars, markers) are 3D and positioned; UI, music and the van&#39;s own engine are 2D.</li><li><strong>Variation:</strong> every repeated sound (hits, blips, ticks, tyre squeal) has at least 3 variants or random pitch ±5% <mark class="tune">TUNE</mark> so it does not fatigue.</li><li><strong>Slow motion and pause:</strong> slow motion lowers pitch on effects, not on music or UI; pause mutes the world and keeps UI sounds.</li><li>Graybox first: placeholders (free libraries or generated) are fine for the MVP; every row below needs at least a placeholder before playtests.</li></ol><h2 id="music" tabindex="-1">Music <a class="header-anchor" href="#music" aria-label="Permalink to &quot;Music&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Id</th><th>Where</th><th>Notes</th></tr></thead><tbody><tr><td><code>mus-menu</code></td><td>Main menu, settings</td><td>Loop; sets the comedic Greek tone</td></tr><tr><td><code>mus-hub</code></td><td>Garage hub, report, card draw</td><td>Calm loop</td></tr><tr><td><code>mus-shift</code></td><td>Day shift</td><td>Upbeat driving loop; one layer intensity per trial <mark class="tune">TUNE</mark></td></tr><tr><td><code>mus-overtime</code></td><td>Overtime</td><td>Tense layer or stinger switch on <code>overtimeStarted</code>; returns to calm at HQ</td></tr><tr><td><code>mus-boss</code></td><td>Boss shift (Charon vs Iris)</td><td>Own track</td></tr><tr><td><code>mus-gameover</code> / <code>mus-ending</code></td><td>Game-over and ending screens</td><td>Short stingers or loops</td></tr></tbody></table><h2 id="van-and-driving" tabindex="-1">Van and driving <a class="header-anchor" href="#van-and-driving" aria-label="Permalink to &quot;Van and driving&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Id</th><th>Trigger</th><th>Notes</th></tr></thead><tbody><tr><td><code>engine</code></td><td>Always while driving</td><td>Loop, pitch and volume from speed and throttle; rougher when damaged (<a class="decision-ref" href="/hex-gdd/GDD#d-079">D‑079</a>)</td></tr><tr><td><code>tyre-squeal</code></td><td>Drift (<code>driftStarted</code>)</td><td>Loop while drifting</td></tr><tr><td><code>nitro</code></td><td><code>boostStarted</code> / end</td><td>Whoosh start, loop, tail</td></tr><tr><td><code>wind</code></td><td>Near top speed</td><td>Loop scaled by <code>speed01</code></td></tr><tr><td><code>crash</code> / <code>bump</code></td><td><code>crash</code> hazard hit</td><td>Two weights, matching 1 HP and 0.5 HP</td></tr><tr><td><code>brake</code> / <code>reverse-beep</code></td><td>Braking hard, reversing</td><td>Optional, comedic</td></tr></tbody></table><h2 id="packages-and-money" tabindex="-1">Packages and money <a class="header-anchor" href="#packages-and-money" aria-label="Permalink to &quot;Packages and money&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Id</th><th>Trigger</th><th>Notes</th></tr></thead><tbody><tr><td><code>pickup</code></td><td><code>jobPickedUp</code></td><td>Blip</td></tr><tr><td><code>deliver</code></td><td><code>delivered</code></td><td>Rising cash-register ticks</td></tr><tr><td><code>marker-near</code></td><td>Van enters a pickup or drop zone</td><td>Soft cue that <code>{interact}</code> is ready</td></tr><tr><td><code>scam-reels</code> / <code>jackpot</code> / <code>bust</code></td><td><code>scamResolved</code></td><td>Reel ticks, jingle or boom</td></tr><tr><td><code>zeus-blessing</code></td><td>Zeus&#39;s ward start / end</td><td>Hum and fade</td></tr></tbody></table><h2 id="hazards-and-damage" tabindex="-1">Hazards and damage <a class="header-anchor" href="#hazards-and-damage" aria-label="Permalink to &quot;Hazards and damage&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Id</th><th>Trigger</th><th>Notes</th></tr></thead><tbody><tr><td><code>strike-warn</code></td><td><code>strike</code> telegraph</td><td>Crackle that builds over the warning time; 3D, audible behind the camera</td></tr><tr><td><code>strike-hit</code></td><td>Strike lands</td><td>Thunder; louder near the van</td></tr><tr><td><code>big-strike-warn</code> / <code>big-strike-hit</code></td><td><code>big-strike</code></td><td>Deeper, longer than <code>strike</code></td></tr><tr><td><code>shield-block</code></td><td>Shield or ward absorbs a hit</td><td>Chime</td></tr><tr><td><code>boundary-alarm</code></td><td><code>boundary</code> countdown</td><td>Ticking alarm per second</td></tr><tr><td><code>hp-loss</code></td><td><code>hpChanged</code> (loss)</td><td>Thud</td></tr><tr><td><code>low-hp</code></td><td>HP ≤ 3</td><td>Heartbeat loop</td></tr><tr><td><code>wreck</code></td><td><code>wreckStarted</code></td><td>Explosion</td></tr><tr><td><code>repair</code></td><td><code>repairPurchased</code></td><td>Wrench clinks</td></tr></tbody></table><h2 id="day-and-world" tabindex="-1">Day and world <a class="header-anchor" href="#day-and-world" aria-label="Permalink to &quot;Day and world&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Id</th><th>Trigger</th><th>Notes</th></tr></thead><tbody><tr><td><code>amb-city</code></td><td>Day shift</td><td>City loop: traffic, birds</td></tr><tr><td><code>amb-storm</code></td><td>Overtime</td><td>Rain and distant thunder loop</td></tr><tr><td><code>overtime-alarm</code></td><td><code>overtimeStarted</code></td><td>Alarm sting</td></tr><tr><td><code>day-start</code></td><td><code>dayStarted</code></td><td>Short horn or bell</td></tr><tr><td><code>hq-arrive</code></td><td>Van reaches HQ</td><td>Relief cue</td></tr></tbody></table><h2 id="ui-and-voice" tabindex="-1">UI and voice <a class="header-anchor" href="#ui-and-voice" aria-label="Permalink to &quot;UI and voice&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Id</th><th>Trigger</th><th>Notes</th></tr></thead><tbody><tr><td><code>ui-move</code> / <code>ui-confirm</code> / <code>ui-back</code> / <code>ui-locked</code></td><td>Menu focus, confirm, back, disabled button</td><td>Short clicks</td></tr><tr><td><code>report-tick</code> / <code>stamp</code></td><td>Report count-up, verdict stamp</td><td>SUCCESS and FAILED variants</td></tr><tr><td><code>card-deal</code> / <code>card-flip</code> / <code>card-pick</code> / <code>reroll</code></td><td>Card draw</td><td></td></tr><tr><td><code>voice-blip</code></td><td>Dialogue text, per letter</td><td>One pitch per character (Hermes, Charon, Iris) — no recorded voice in the MVP</td></tr></tbody></table><h2 id="numbers" tabindex="-1">Numbers <a class="header-anchor" href="#numbers" aria-label="Permalink to &quot;Numbers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Value</th><th>Unit</th><th>What to watch in playtests</th></tr></thead><tbody><tr><td>Default volumes Master / Music / Effects</td><td>80 / 60 / 80 <mark class="tune">TUNE</mark></td><td>%</td><td>Music never hides warnings</td></tr><tr><td>Music duck under scam and wreck</td><td>−8 <mark class="tune">TUNE</mark></td><td>dB</td><td></td></tr><tr><td>Random pitch on repeated sounds</td><td>±5 <mark class="tune">TUNE</mark></td><td>%</td><td></td></tr><tr><td>Music crossfade</td><td>1 <mark class="tune">TUNE</mark></td><td>s</td><td></td></tr></tbody></table><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><ul><li>Music source: original, commissioned, or licensed library.</li><li>Does trial intensity add music layers, or only change ambience?</li></ul><h2 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to &quot;History&quot;">​</a></h2><ul><li>2026-11-19: idea; asset list drafted from the feedback, hazards, driving and screen specs (<a class="decision-ref" href="/hex-gdd/GDD#d-081">D‑081</a>).</li></ul>',23)])])}const b=e(o,[["render",s]]);export{m as __pageData,b as default};
